// ==================== HELPER FUNCTIONS ====================
export const getLocationName = (id: string): string => {
  return MOCK_LOCATIONS.find(l => l.id === id)?.ten_vi_tri || 'Không xác định';
};

export const getDeviceName = (id: string): string => {
  return MOCK_DEVICES.find(d => d.id === id)?.ten_tai_san || 'Không xác định';
};

export const getAssetHistoryByDevice = (deviceId: string): AssetHistory[] => {
  return MOCK_ASSET_HISTORY
    .filter(h => h.id_tai_san === deviceId)
    .sort((a, b) => new Date(b.ngay_thuc_hien).getTime() - new Date(a.ngay_thuc_hien).getTime());
};

export const getSchedulesByStatus = (status: 'active' | 'inactive'): MaintenanceSchedule[] => {
  return MOCK_MAINTENANCE_SCHEDULES.filter(s => s.trang_thai === status);
};

export const getUpcomingSchedules = (days: number = 30): MaintenanceSchedule[] => {
  const now = new Date();
  const futureDate = new Date(now.getTime() + days * 24 * 60 * 60 * 1000);
  
  return MOCK_MAINTENANCE_SCHEDULES
    .filter(s => {
      const nextDate = new Date(s.ngay_bao_tri_tiep_theo);
      return s.trang_thai === 'active' && nextDate >= now && nextDate <= futureDate;
    })
    .sort((a, b) => new Date(a.ngay_bao_tri_tiep_theo).getTime() - new Date(b.ngay_bao_tri_tiep_theo).getTime());
};

export const getDevicesByLocation = (locationId: string): Device[] => {
  return MOCK_DEVICES.filter(d => d.id_vi_tri === locationId);
};

export const getDevicesByStatus = (status: 0 | 1 | 2 | 3 | 4): Device[] => {
  return MOCK_DEVICES.filter(d => d.trang_thai === status);
};
